        let fillBytes = (i == S().gen2_active_chunk) ? (S().gen2_offset - chunkStart) : AST_CHUNK_SIZE;
        if (fillBytes > 0 && fillBytes <= AST_CHUNK_SIZE) memory.fill(chunkStart as usize, 0, fillBytes as usize);
