export function pushTokenToBuffer(tok: i32, len: u32): void {
  let idx = tokenBufferWriteIdx & (ARENA_BUFFER_SIZE - 1);
  t_tokenBufferArena[idx] = tok;
  t_tokenBufferLenArena[idx] = len;
  tokenBufferWriteIdx++;
}

